import http from 'k6/http';
import { check } from 'k6';
import { Counter } from 'k6/metrics';

// Custom metrics for auditing
const successfulReservations = new Counter('successful_reservations');
const rejectedReservations = new Counter('rejected_reservations');
const otherErrors = new Counter('other_errors');

// Read test-data.json generated by setup script (resolved relative to this file)
let testData = null;
try {
    testData = JSON.parse(open('./test-data.json'));
} catch (e) {
    // Fallback if test-data.json is not yet created
}

export const options = {
    scenarios: {
        flash_sale_rush: {
            executor: 'per-vu-iterations',
            vus: 100,
            iterations: 1,
            maxDuration: '30s',
        },
    },
    thresholds: {
        // Zero unhandled 500 Internal Server Errors permitted
        'other_errors': ['count==0'],
        // p95 latency for successful reservations must remain well below operational limit (800ms)
        'http_req_duration{status:201}': ['p(95)<800', 'p(99)<1500'],
        // Successful reservations must match exactly available stock (10 tickets)
        'successful_reservations': ['count<=10'],
    },
};

const BASE_URL = __ENV.API_URL || 'http://localhost:3000';
const TARGET_TIER_ID = __ENV.TIER_ID || (testData && testData.tierId);

export default function () {
    if (!TARGET_TIER_ID) {
        throw new Error('TIER_ID was not defined! Run npm run load:setup or pass via -e TIER_ID="<uuid>"');
    }

    // Assign a unique authenticated user token per Virtual User
    let authToken = null;
    if (testData && testData.tokens && testData.tokens.length > 0) {
        const tokenIndex = (__VU - 1) % testData.tokens.length;
        authToken = testData.tokens[tokenIndex];
    }

    const idempotencyKey = `idemp-vu-${__VU}-${Date.now()}`;

    const payload = JSON.stringify({
        ticketTierId: TARGET_TIER_ID,
        quantity: 1,
    });

    const headers = {
        'Content-Type': 'application/json',
        'x-idempotency-key': idempotencyKey,
    };

    if (authToken) {
        headers['Authorization'] = `Bearer ${authToken}`;
    }

    const res = http.post(`${BASE_URL}/reservations`, payload, { headers });

    if (res.status === 201) {
        successfulReservations.add(1);
        check(res, {
            'status is 201 Created': (r) => r.status === 201,
        });
    } else if (res.status === 400 || res.status === 409) {
        rejectedReservations.add(1);
        check(res, {
            'status is 400 Bad Request or 409 Conflict': (r) => r.status === 400 || r.status === 409,
        });
    } else {
        otherErrors.add(1);
        console.error(`[VU ${__VU}] Unexpected status [${res.status}]: ${res.body}`);
    }
}